// App.js
import React, { useState, useEffect } from 'react';
import { fetchResorts, fetchResort } from './api';
import ResortList from './components/ResortList';
import Search from './components/Search'; // Import Search component

function App() {
  const [resorts, setResorts] = useState([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    const loadResorts = async () => {
      setLoading(true);
      try {
        const data = await fetchResorts();
        if (Array.isArray(data)) {
          setResorts(data);
        } else {
          console.error('Unexpected data format:', data);
          setError('Unexpected data format');
        }
      } catch (error) {
        console.error('Error loading resorts:', error);
        setError('Error loading resorts');
      } finally {
        setLoading(false);
      }
    };

    loadResorts();
  }, []);

  const handleSearch = async (searchResults) => {
    setResorts(searchResults);
  };

  return (
    <div>
      <Search onSearch={handleSearch} />
      {loading && <p>Loading...</p>}
      {error && <p>{error}</p>}
      <ResortList resorts={resorts} />
    </div>
  );
}

export default App;
